components.css:
.ds-btn-primary { padding: 0.5rem 1rem; background: #0052ff; color: #ffffff; border: 1px solid #1a1c1c; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; box-shadow: 2px 2px 0 0 #1a1c1c; }
.ds-btn-primary:hover:not(:disabled) { background: #0038b6; border-color: #0038b6; }
.ds-btn-primary:active:not(:disabled) { box-shadow: none; transform: translate(2px, 2px); }
.ds-btn-primary:disabled { opacity: 0.6; cursor: default; }
.ds-btn-primary:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }

.ds-btn-secondary { padding: 0.5rem 1rem; background: #ffffff; color: #1a1c1c; border: 1px solid #1a1c1c; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; box-shadow: 2px 2px 0 0 #1a1c1c; }
.ds-btn-secondary:hover:not(:disabled) { background: #f3f3f3; }
.ds-btn-secondary:active:not(:disabled) { box-shadow: none; transform: translate(2px, 2px); }
.ds-btn-secondary:disabled { opacity: 0.6; cursor: default; }
.ds-btn-secondary:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }

.ds-btn-danger { padding: 0.5rem 1rem; background: #ba1a1a; color: #ffffff; border: 1px solid #1a1c1c; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; box-shadow: 2px 2px 0 0 #1a1c1c; }
.ds-btn-danger:hover:not(:disabled) { background: #93000a; }
.ds-btn-danger:active:not(:disabled) { box-shadow: none; transform: translate(2px, 2px); }
.ds-btn-danger:focus-visible { outline: 2px solid #ba1a1a; outline-offset: 2px; }

.ds-field { display: flex; flex-direction: column; font-family: inherit; }
.ds-field > span { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; line-height: 1; color: #1a1c1c; }
.ds-field__input { box-sizing: border-box; margin-top: 0.25rem; width: 100%; padding: 0.5rem; border: 1px solid #1a1c1c; border-radius: 0; background: #ffffff; color: #1a1c1c; font-family: inherit; font-size: 1rem; font-weight: 400; line-height: 1.5; }
.ds-field__input--data { font-family: ui-monospace, 'JetBrains Mono', Consolas, monospace; font-variant-numeric: tabular-nums; font-size: 0.875rem; }
.ds-field__input:focus, .ds-field__input:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }

.ds-card { background: #ffffff; border: 1px solid #1a1c1c; border-radius: 0; padding: 1rem; font-family: inherit; }
.ds-card__header { margin: 0 0 1.5rem; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; line-height: 1; color: #1a1c1c; }
.ds-card__lede { margin: 0; font-size: 0.875rem; color: #434656; }

.ds-nav { display: flex; flex-direction: column; border-right: 1px solid #1a1c1c; font-family: inherit; }
.ds-nav__link { display: block; padding: 0.5rem 1rem; text-decoration: none; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; line-height: 1; color: #1a1c1c; border-left: 4px solid transparent; }
.ds-nav__link:hover { background: #eeeeee; }
.ds-nav__link--active { background: #dde1ff; border-left-color: #003ec7; }
.ds-nav__link:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }

.ds-strip { display: flex; align-items: center; flex-wrap: wrap; gap: 0.5rem; box-sizing: border-box; width: 100%; padding: 0.6rem max(1rem, calc((100% - 800px) / 2)); background: #dde1ff; border-bottom: 1px solid #003ec7; font-family: inherit; }
.ds-strip__message { flex: 1 1 auto; min-width: 0; font-size: 0.875rem; line-height: 1.4; color: #001452; }
.ds-strip__action { flex-shrink: 0; padding: 0.25rem 0.5rem; background: #0052ff; color: #ffffff; border: 1px solid #1a1c1c; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; box-shadow: 2px 2px 0 0 #1a1c1c; }
.ds-strip__action:hover:not(:disabled) { background: #0038b6; border-color: #0038b6; }
.ds-strip__action:active:not(:disabled) { box-shadow: none; transform: translate(2px, 2px); }
.ds-strip__action:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }
@media (pointer: coarse) { .ds-strip__action { min-height: 44px; } }

.ds-row { display: flex; align-items: center; gap: 0.75rem; padding: 0.5rem 0.5rem; border-bottom: 1px solid #f3f3f3; border-left: 4px solid #ba1a1a; font-family: inherit; }
.ds-row--income { border-left-color: #15803d; }
.ds-row--expense { border-left-color: #ba1a1a; }
.ds-row--transfer { border-left-color: #737688; }
.ds-row__date { font-size: 0.875rem; color: #434656; font-variant-numeric: tabular-nums; }
.ds-row__category { font-size: 1rem; color: #1a1c1c; }
.ds-row__amount { margin-left: auto; font-family: ui-monospace, 'JetBrains Mono', Consolas, monospace; font-variant-numeric: tabular-nums; font-size: 0.875rem; font-weight: 500; color: #ba1a1a; }
.ds-row--income .ds-row__amount { color: #15803d; }
.ds-row--transfer .ds-row__amount { color: #1a1c1c; }
.ds-row__actions { display: inline-flex; gap: 0.25rem; }
.ds-row__icon { display: inline-flex; align-items: center; justify-content: center; width: 1.75rem; height: 1.75rem; padding: 0; border: 1px solid transparent; border-radius: 0; background: none; cursor: pointer; color: #434656; }
.ds-row__icon svg { width: 1rem; height: 1rem; }
.ds-row__icon:hover { background: #f5f5f5; }
.ds-row__icon:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }
@media (pointer: coarse) { .ds-row__icon { width: 2.75rem; height: 2.75rem; border: none; box-shadow: none; } .ds-row__icon svg { width: 1.25rem; height: 1.25rem; } }

.ds-empty { margin: 0; padding: 1.5rem; text-align: center; background: #ffffff; border: 1px dashed #737688; border-radius: 0; font-family: inherit; font-size: 1rem; color: #434656; }
.ds-empty__action { margin-left: 0.25rem; padding: 0.25rem 0.5rem; background: #ffffff; color: #1a1c1c; border: 1px solid #1a1c1c; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; box-shadow: 2px 2px 0 0 #1a1c1c; }
.ds-empty__action:active:not(:disabled) { box-shadow: none; transform: translate(2px, 2px); }
.ds-empty__action:focus-visible { outline: 2px solid #003ec7; outline-offset: 2px; }
